import { afterEach, describe, expect, it, vi } from "vitest";
// The payloads cxp-api serializes (generated by the Rust test `wire_fixture`).
import wire from "../../../../crates/cxp-api/tests/fixtures/wire.json";
import { customersApi } from "./api/customers";
import { experiencesApi } from "./api/experiences";
import type {
  Application,
  Component,
  Customer,
  Customer360,
  DashboardMetrics,
  Experience,
  Feedback,
  FeedbackSummary,
  Interaction,
  MyTeam,
  Page,
  PaginatedResponse,
  Survey,
  SurveyResponse,
  Ticket,
  TicketSummary,
} from "./types";

// `Record<keyof T, true>` is exhaustive in both directions at compile time, so
// each list below is exactly the fields of the interface; the tests then hold
// the server's payload to the same list.
const keys = {
  customer: { id: true, email: true, name: true, phone: true, company: true, metadata: true, tags: true, experienceId: true, applicationId: true, pageId: true, componentId: true, createdAt: true, updatedAt: true } satisfies Record<keyof Customer, true>,
  ticket: { id: true, customerId: true, subject: true, description: true, status: true, priority: true, channel: true, assignedTo: true, tags: true, metadata: true, experienceId: true, applicationId: true, pageId: true, componentId: true, resolvedAt: true, createdAt: true, updatedAt: true } satisfies Record<keyof Ticket, true>,
  ticketSummary: { id: true, subject: true, status: true, priority: true, channel: true, assignedTo: true, createdAt: true, resolvedAt: true } satisfies Record<keyof TicketSummary, true>,
  feedback: { id: true, customerId: true, feedbackType: true, subject: true, body: true, rating: true, metadata: true, experienceId: true, applicationId: true, pageId: true, componentId: true, createdAt: true } satisfies Record<keyof Feedback, true>,
  feedbackSummary: { id: true, feedbackType: true, subject: true, body: true, rating: true, createdAt: true } satisfies Record<keyof FeedbackSummary, true>,
  survey: { id: true, title: true, description: true, questions: true, active: true, experienceId: true, applicationId: true, pageId: true, componentId: true, createdAt: true, updatedAt: true } satisfies Record<keyof Survey, true>,
  surveyResponse: { id: true, surveyId: true, customerId: true, answers: true, completedAt: true, createdAt: true } satisfies Record<keyof SurveyResponse, true>,
  interaction: { id: true, customerId: true, interactionType: true, metadata: true, createdAt: true } satisfies Record<keyof Interaction, true>,
  experience: { id: true, name: true, description: true, teamId: true, metadata: true, createdAt: true, updatedAt: true } satisfies Record<keyof Experience, true>,
  application: { id: true, experienceId: true, teamId: true, name: true, description: true, platform: true, metadata: true, createdAt: true, updatedAt: true } satisfies Record<keyof Application, true>,
  page: { id: true, applicationId: true, teamId: true, name: true, path: true, description: true, metadata: true, createdAt: true, updatedAt: true } satisfies Record<keyof Page, true>,
  component: { id: true, pageId: true, teamId: true, name: true, componentType: true, description: true, metadata: true, createdAt: true, updatedAt: true } satisfies Record<keyof Component, true>,
  customer360: { customer: true, recentTickets: true, recentInteractions: true, recentFeedback: true } satisfies Record<keyof Customer360, true>,
  team: { id: true, slug: true, name: true } satisfies Record<keyof MyTeam, true>,
  dashboardMetrics: { total_customers: true, total_tickets: true, open_tickets: true, total_feedback: true, total_surveys: true, total_experiences: true } satisfies Record<keyof DashboardMetrics, true>,
  paginated: { data: true, total: true, limit: true, offset: true } satisfies Record<keyof PaginatedResponse<unknown>, true>,
};

function sameKeys(actual: object, expected: object) {
  expect(Object.keys(actual).sort()).toEqual(Object.keys(expected).sort());
}

// These assignments fail `tsc` if a fixture field is missing or mistyped.
const typed = {
  customer: wire.customer satisfies Customer,
  customerMinimal: wire.customerMinimal satisfies Customer,
  ticket: wire.ticket satisfies Ticket,
  ticketOpen: wire.ticketOpen satisfies Ticket,
  feedback: wire.feedback satisfies Feedback,
  survey: wire.survey satisfies Survey,
  surveyResponse: wire.surveyResponse satisfies SurveyResponse,
  interaction: wire.interaction satisfies Interaction,
  experience: wire.experience satisfies Experience,
  application: wire.application satisfies Application,
  page: wire.page satisfies Page,
  component: wire.component satisfies Component,
  customer360: wire.customer360 satisfies Customer360,
  team: wire.team satisfies MyTeam,
  dashboardMetrics: wire.dashboardMetrics satisfies DashboardMetrics,
  customerList: wire.customerList satisfies PaginatedResponse<Customer>,
  ticketList: wire.ticketList satisfies PaginatedResponse<Ticket>,
  feedbackList: wire.feedbackList satisfies PaginatedResponse<Feedback>,
  surveyList: wire.surveyList satisfies PaginatedResponse<Survey>,
  experienceList: wire.experienceList satisfies PaginatedResponse<Experience>,
  applicationList: wire.applicationList satisfies PaginatedResponse<Application>,
  pageList: wire.pageList satisfies PaginatedResponse<Page>,
  componentList: wire.componentList satisfies PaginatedResponse<Component>,
};

describe("types match the server's JSON", () => {
  it("models carry exactly the declared fields", () => {
    sameKeys(typed.customer, keys.customer);
    sameKeys(typed.ticket, keys.ticket);
    sameKeys(typed.customerMinimal, keys.customer);
    sameKeys(typed.ticketOpen, keys.ticket);
    sameKeys(typed.feedback, keys.feedback);
    sameKeys(typed.survey, keys.survey);
    sameKeys(typed.surveyResponse, keys.surveyResponse);
    sameKeys(typed.interaction, keys.interaction);
    sameKeys(typed.experience, keys.experience);
    sameKeys(typed.application, keys.application);
    sameKeys(typed.page, keys.page);
    sameKeys(typed.component, keys.component);
    sameKeys(typed.team, keys.team);
    sameKeys(typed.dashboardMetrics, keys.dashboardMetrics);
  });

  it("the customer 360 view nests summaries, not full rows", () => {
    sameKeys(typed.customer360, keys.customer360);
    sameKeys(typed.customer360.customer, keys.customer);
    sameKeys(typed.customer360.recentTickets[0], keys.ticketSummary);
    sameKeys(typed.customer360.recentFeedback[0], keys.feedbackSummary);
    sameKeys(typed.customer360.recentInteractions[0], keys.interaction);
  });

  it("optional fields are present as null, not absent", () => {
    const { customerMinimal: c, ticketOpen: t } = typed;
    expect([c.name, c.phone, c.company]).toEqual([null, null, null]);
    expect([c.experienceId, c.applicationId, c.pageId, c.componentId]).toEqual([null, null, null, null]);
    expect([t.description, t.channel, t.assignedTo, t.resolvedAt]).toEqual([null, null, null, null]);
  });

  it("list responses use the data/total/limit/offset envelope", () => {
    const lists = [
      [typed.customerList, keys.customer],
      [typed.ticketList, keys.ticket],
      [typed.feedbackList, keys.feedback],
      [typed.surveyList, keys.survey],
      [typed.experienceList, keys.experience],
      [typed.applicationList, keys.application],
      [typed.pageList, keys.page],
      [typed.componentList, keys.component],
    ] as const;
    for (const [list, rowKeys] of lists) {
      sameKeys(list, keys.paginated);
      expect(list.data).toHaveLength(1);
      sameKeys(list.data[0], rowKeys);
    }
  });

  it("only the dashboard metrics keep snake_case keys", () => {
    const snake = (value: unknown, path: string): string[] => {
      if (Array.isArray(value)) {
        return value.flatMap((v, i) => snake(v, `${path}[${i}]`));
      }
      if (value && typeof value === "object") {
        return Object.entries(value).flatMap(([k, v]) =>
          // metadata/answers/questions hold caller-defined JSON.
          ["metadata", "answers", "questions"].includes(k)
            ? []
            : [...(k.includes("_") ? [`${path}.${k}`] : []), ...snake(v, `${path}.${k}`)],
        );
      }
      return [];
    };
    const { dashboardMetrics: _metrics, ...rest } = wire;
    expect(snake(rest, "wire")).toEqual([]);
  });
});

describe("api calls decode the server's payloads", () => {
  afterEach(() => vi.unstubAllGlobals());

  function respondWith(body: unknown) {
    vi.stubGlobal(
      "fetch",
      vi.fn(async () => new Response(JSON.stringify(body), { status: 200 })),
    );
  }

  it("a catalog list exposes timestamps and team references", async () => {
    respondWith(wire.experienceList);
    const page = await experiencesApi.list();
    const [experience] = page.data;
    expect(experience.createdAt).toBe("2026-10-10T12:30:00Z");
    expect(new Date(experience.createdAt).getTime()).not.toBeNaN();
    expect(experience.teamId).toBe(wire.team.id);
  });

  it("a customer 360 exposes its recent rows", async () => {
    respondWith(wire.customer360);
    const view = await customersApi.get360(wire.customer.id);
    expect(view.customer.createdAt).toBe("2026-10-01T12:30:00Z");
    expect(view.recentTickets[0].createdAt).toBe("2026-10-03T12:30:00Z");
    expect(view.recentFeedback[0].feedbackType).toBe("nps");
    expect(view.recentInteractions[0].interactionType).toBe("page_view");
  });
});
